# GF(8) with primitive poly x^3 + x + 1 (0b1011)
def gf_mul(a, b):
    r = 0
    for i in range(3):
        if (b >> i) & 1:
            r ^= a << i
    # reduce mod x^3+x+1 (0b1011)
    for i in range(5, 2, -1):
        if (r >> i) & 1:
            r ^= 0b1011 << (i - 3)
    return r

# Verify it's a field
prods = set()
for a in range(1,8):
    for b in range(1,8):
        prods.add(gf_mul(a,b))
print(prods)

# Two MOLS: X[i][j] = i XOR (1*j) wait that's not orthogonal with itself
# L_c[i][j] = i + c*j in GF(8). Two different c values give orthogonal squares.
def make(c):
    return [[i ^ gf_mul(c, j) for j in range(8)] for i in range(8)]

X = make(1)  # c=1: X[i][j] = i XOR j
Y = make(2)  # c=2

# Check Latin
def is_latin(M):
    for row in M:
        if set(row) != set(range(8)): return False
    for j in range(8):
        if set(M[i][j] for i in range(8)) != set(range(8)): return False
    return True

print(is_latin(X), is_latin(Y))
pairs = set()
for i in range(8):
    for j in range(8):
        pairs.add((X[i][j], Y[i][j]))
print(len(pairs))

result = [X[i][j] for i in range(8) for j in range(8)] + [Y[i][j] for i in range(8) for j in range(8)]
print(result)
